// Generated by Viscosity: "ps" stored as a struct of arrays (fields x, y, vx, vy, mass, age, r, g).
class __Vsc_ps {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.x = new Float64Array(cap); this.y = new Float64Array(cap); this.vx = new Float64Array(cap); this.vy = new Float64Array(cap); this.mass = new Float64Array(cap); this.age = new Float64Array(cap); this.r = new Float64Array(cap); this.g = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_ps(Math.max(16, v.length / 8)); for (let i = 0; i < v.length; i += 8) c.push(v[i + 0], v[i + 1], v[i + 2], v[i + 3], v[i + 4], v[i + 5], v[i + 6], v[i + 7]); return c; }
  push(v0, v1, v2, v3, v4, v5, v6, v7) { const n = this.length; if (n === this.cap) this.grow(); this.x[n] = v0; this.y[n] = v1; this.vx[n] = v2; this.vy[n] = v3; this.mass[n] = v4; this.age[n] = v5; this.r[n] = v6; this.g[n] = v7; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.x); this.x = t; t = new Float64Array(cap); t.set(this.y); this.y = t; t = new Float64Array(cap); t.set(this.vx); this.vx = t; t = new Float64Array(cap); t.set(this.vy); this.vy = t; t = new Float64Array(cap); t.set(this.mass); this.mass = t; t = new Float64Array(cap); t.set(this.age); this.age = t; t = new Float64Array(cap); t.set(this.r); this.r = t; t = new Float64Array(cap); t.set(this.g); this.g = t; }
}
// Particles: 200k particles with 8 fields; the hot loop touches 4.
const N = 200000;
const ps = new __Vsc_ps();
for (let i = 0; i < N; i++) {
  ps.push(i % 1000, (i * 7) % 1000, 1, -1, 1 + (i % 5), 0, 2, 3);
}
function step(arr, dt) {
  for (let i = 0; i < arr.length; i++) {
    const p = i;
    arr.x[p] += arr.vx[p] * dt;
    arr.y[p] += arr.vy[p] * dt;
  }
}
const t0 = performance.now();
for (let f = 0; f < 200; f++) step(ps, 0.016);
const ms = performance.now() - t0;
let s = 0;
for (let p = 0; p < ps.length; p++) s += ps.x[p] + ps.y[p];
console.log(JSON.stringify({ check: s.toFixed(3), ms }));
